			{"lesson": "4-2", "question": "How do ROS 2 nodes find each other?", "choices": ["They register with roscore","They discover each other automatically through DDS, with no master","Through a cloud server","They must be listed by hand in a file"], "answer": 1, "explanation": "ROS 2 replaces the central roscore master with Data Distribution Service (DDS), which discovers peer nodes automatically via network multicast."},
			{"lesson": "4-2", "question": "A subscriber requests 'Reliable' reliability on a topic, but the publisher offers 'Best Effort'. What happens?", "choices": ["The publisher automatically upgrades its protocol to Reliable","The connection fails and no messages are delivered due to a QoS incompatibility","The message data is stored on a cloud server instead","The subscriber drops its request and accepts whatever is sent"], "answer": 1, "explanation": "In ROS 2, a connection requires Offered QoS >= Requested QoS. A Reliable subscriber requires a Reliable publisher; connecting it to a Best Effort publisher causes a QoS mismatch."},
			{"lesson": "4-2", "question": "How can an engineer switch the underlying middleware implementation in ROS 2 (e.g. from Fast DDS to Cyclone DDS or Zenoh)?", "choices": ["By modifying and recompiling the Linux kernel","By setting the RMW_IMPLEMENTATION environment variable before running nodes","By re-soldering the robot's Ethernet transceiver","By rewriting all publisher and subscriber code in C++"], "answer": 1, "explanation": "Because of the ROS Middleware (RMW) abstraction layer, changing middleware simply requires setting the RMW_IMPLEMENTATION environment variable in the terminal."},
			{"lesson": "4-3", "question": "Why do you run 'source /opt/ros/lyrical/setup.bash'?", "choices": ["To download ROS","So the ros2 command can be found in that terminal","To update Ubuntu","To start Turtlesim"], "answer": 1, "explanation": "Sourcing setup.bash sets up essential environment variables like PATH, AMENT_PREFIX_PATH, and PYTHONPATH so the ros2 CLI tools and libraries can be found."},
			{"lesson": "4-3", "question": "Why does the ROS 2 installation guide require configuring a UTF-8 locale (such as en_US.UTF-8)?", "choices": ["Without UTF-8, robot motors will run in reverse", "ROS 2 tools expect a UTF-8 locale, and minimal systems such as Docker containers may default to a non-UTF-8 POSIX locale", "DDS middleware only operates on computers located in the United States", "UTF-8 is required to connect to Wi-Fi networks"], "answer": 1, "explanation": "The official install guide says to make sure the locale supports UTF-8 before installing, because minimal environments such as Docker containers may use a POSIX locale by default."},
			{"lesson": "4-3", "question": "If two ROS 2 nodes running on the same local network cannot discover each other, which firewall setting should you inspect?", "choices": ["HTTP port 80","SSH port 22","UDP multicast traffic on 224.0.0.0/4 used by DDS discovery","DNS port 53"], "answer": 2, "explanation": "DDS peer discovery broadcasts over UDP multicast (subnet 224.0.0.0/4). If the host firewall blocks UDP multicast, nodes cannot discover each other."},
			{"lesson": "4-4", "question": "In Turtlesim, which topic carries the velocity commands from the teleop node?", "choices": ["/turtle1/pose","/turtle1/cmd_vel","/rosout","/parameter_events"], "answer": 1, "explanation": "The teleop node publishes on /turtle1/cmd_vel and the simulator subscribes to it to move the simulated turtle."},
			{"lesson": "4-4", "question": "In a standard ROS 2 workspace (ros2_ws), where must developer source code packages be placed?", "choices": ["Inside /opt/ros/lyrical/","Inside the src/ directory","Inside the build/ directory","Directly in the user's home folder"], "answer": 1, "explanation": "Source code packages must be located in the src/ directory. The build/, install/, and log/ directories are generated automatically by colcon."},
			{"lesson": "4-4", "question": "In an rclpy Python node script, what is the primary role of calling rclpy.spin(node)?", "choices": ["It spins the physical robot motors at maximum speed","It blocks execution to keep the node alive and process incoming callbacks from timers and subscriptions","It deletes temporary compiler files from disk","It downloads missing packages from the Ubuntu repository"], "answer": 1, "explanation": "rclpy.spin() blocks the main thread, entering an event loop that executes callbacks whenever a timer fires or a message arrives on a subscribed topic."},
			{"lesson": "4-5", "question": "What is the difference between RViz and Gazebo?", "choices": ["They are the same tool","RViz displays data already flowing through ROS; Gazebo simulates the robot and its world with physics","RViz simulates physics; Gazebo only draws maps","Gazebo is for ROS 1 only"], "answer": 1, "explanation": "RViz visualizes telemetry already flowing across topics and simulates nothing. Gazebo is a multi-physics simulator that models mass, friction, gravity, and sensors."},
			{"lesson": "4-5", "question": "Which tool records messages on chosen topics so you can replay them later without the robot?", "choices": ["rqt_graph","ros2 bag","RViz","tf2"], "answer": 1, "explanation": "ros2 bag record serializes topic messages into storage files, and ros2 bag play republishes them with original timestamps."},
			{"lesson": "4-5", "question": "In the rqt_graph visual interface, how are computational entities displayed?", "choices": ["Nodes are drawn as ovals and topics are drawn as rectangles, connected by directed communication arrows","Nodes are drawn as 3D meshes and topics are drawn as audio waveforms","Everything is represented as a text terminal spreadsheet","Topics are drawn as circles and nodes are hidden"], "answer": 0, "explanation": "rqt_graph renders active nodes as ovals and communication topics as boxes or labeled arrows, illustrating pub/sub relationships."},
			{"lesson": "4-6", "question": "You run ros2 pkg create my_pkg without a --build-type option on Lyrical. What kind of package do you get?", "choices": ["An ament_python package", "An ament_cmake (C++) package", "An ament_cargo (Rust) package", "The command fails and asks for a build type"], "answer": 1, "explanation": "In the Lyrical source of ros2 pkg create, --build-type still defaults to ament_cmake, so you must pass --build-type ament_python for a Python package."},
			{"lesson": "4-6", "question": "Why does the square driver publish velocity commands from a 10 Hz timer instead of sending one message per side?", "choices": ["Twist messages expire after 0.1 s by QoS", "Turtlesim sets all velocities to zero if no cmd_vel message arrives for more than 1.0 s", "rclpy can only publish inside a timer callback", "Turtlesim ignores the first message on each topic"], "answer": 1, "explanation": "Turtlesim's source stops the turtle when more than 1.0 s passes since the last cmd_vel message, so the node must keep publishing."},
			{"lesson": "4-6", "question": "On ROS 2 Lyrical, which import gives you Turtlesim's Pose message?", "choices": ["from turtlesim.msg import Pose", "from geometry_msgs.msg import Pose", "from turtlesim_msgs.msg import Pose", "from std_msgs.msg import Pose"], "answer": 2, "explanation": "Starting with Kilted, Turtlesim's interfaces moved to the turtlesim_msgs package; turtlesim.msg only exists on Humble and Jazzy."},
			{"lesson": "4-7", "question": "In a Python launch file, what must the generate_launch_description() function return?", "choices": ["A list of shell commands", "A LaunchDescription containing the actions to run", "A YAML parameter dictionary", "The process ID of the first node"], "answer": 1, "explanation": "The ros2 launch command calls generate_launch_description(), which must return a LaunchDescription: a list of actions, such as Node actions, for the launch system to carry out."},
			{"lesson": "4-7", "question": "Where are parameters stored in ROS 2?", "choices": ["On a global parameter server started by roscore", "On each individual node, which declares and manages its own parameters", "Only inside launch files", "In the colcon build folder"], "answer": 1, "explanation": "ROS 2 has no global parameter server. Parameters are associated with individual nodes, their lifetime is tied to the node, and by default a node must declare every parameter it accepts."},
			{"lesson": "4-7", "question": "In a YAML parameter file, what does the top-level key (for example /turtlesim2/sim) specify?", "choices": ["The package that contains the launch file", "The fully qualified name of the node, including its namespace, that the parameters under it apply to", "The topic the parameters are published on", "The ROS 2 distribution the file was written for"], "answer": 1, "explanation": "Parameters are grouped under the node's fully qualified name and then ros__parameters. A block for /turtlesim2/sim does not affect /turtlesim3/sim; a wildcard such as /** applies to every node."},
			{"lesson": "4-8", "question": "Which launch argument starts the UR driver on ros2_control mock hardware on ROS 2 Lyrical?", "choices": ["use_fake_hardware:=true", "use_mock_hardware:=true", "use_sim_time:=true", "headless_mode:=true"], "answer": 1, "explanation": "The UR driver switches to mock_components/GenericSystem when use_mock_hardware is true. The older name use_fake_hardware was renamed in UR pull request #739, so old tutorials that use it are out of date."},
			{"lesson": "4-8", "question": "Which Pilz planner plans a straight-line tool path, like a MoveL on a teach pendant?", "choices": ["PTP", "CIRC", "LIN", "RRTConnect"], "answer": 2, "explanation": "Pilz LIN plans a linear Cartesian trajectory between the start and goal poses, which matches MoveL. PTP is a synchronized joint move like MoveJ, and CIRC is a circular arc like MoveC."},
			{"lesson": "4-8", "question": "Why is the \"pick\" in this lesson only an approach motion of tool0?", "choices": ["Mock hardware cannot move the wrist joints", "OMPL cannot plan to poses near the floor", "The stock UR description and SRDF define no gripper or end effector", "RViz cannot display the gripper mesh"], "answer": 2, "explanation": "UR's SRDF has an end-effector section with no elements because the default UR description has no gripper, so the lesson plans the tool flange (tool0) to a pre-grasp and grasp pose without closing anything."},
			{"lesson": "4-9", "question": "On ROS 2 Lyrical, which action server does the Universal Robots driver offer by default for trajectory goals?", "choices": ["/scaled_joint_trajectory_controller/follow_joint_trajectory", "/joint_trajectory_controller/follow_joint_trajectory", "/io_and_status_controller/resend_robot_program", "/passthrough_trajectory_controller/forward"], "answer": 1, "explanation": "On the Lyrical and main branches the scaled_joint_trajectory_controller entry is gone; the stock joint_trajectory_controller takes a speed_scaling parameter and is started by default. The scaled controller name is used on Humble, Jazzy and Kilted."},
			{"lesson": "4-9", "question": "Which ABB interface does the community abb_ros2 driver use to stream motion to the robot?", "choices": ["Robot Web Services 2.0 over HTTP", "RSI over a 12 ms cycle", "Externally Guided Motion (EGM) over UDP", "A micro-ROS Agent"], "answer": 2, "explanation": "abb_ros2 moves the robot through EGM, a paid RobotWare option, using its UDP variant; RWS 1.0 over HTTP is used only to read information about the robot."},
			{"lesson": "4-9", "question": "A ROS 2 node sends a trajectory to an industrial arm while a protective stop is active. What decides whether the robot moves?", "choices": ["MoveIt 2's execution monitor", "The ros2_control controller manager", "The robot controller's own certified safety system", "The ROS 2 action server's goal tolerance"], "answer": 2, "explanation": "ROS 2 is not the safety system. The safety functions live in the vendor's controller and keep working whatever the PC sends; ROS only sends requests, and the robot may slow down or stop at any time."}
